<?php require_once __DIR__.'/../includes/admin-auth.php';$pageTitle='Overview';$stats=[];$stats['events']=(int)$pdo->query('SELECT COUNT(*) FROM events')->fetchColumn();$stats['upcoming']=(int)$pdo->query("SELECT COUNT(*) FROM events WHERE status='published' AND event_date>=CURDATE()")->fetchColumn();$stats['registrations']=(int)$pdo->query("SELECT COUNT(*) FROM registrations WHERE status='valid'")->fetchColumn();$stats['checked']=(int)$pdo->query('SELECT COUNT(*) FROM checkins')->fetchColumn();$stats['notchecked']=max(0,$stats['registrations']-$stats['checked']);$stats['participants']=(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn();$events=$pdo->query("SELECT e.id,e.title,e.event_date,e.capacity,e.status,COUNT(r.id) registered FROM events e LEFT JOIN registrations r ON r.event_id=e.id AND r.status='valid' GROUP BY e.id ORDER BY e.event_date DESC LIMIT 6")->fetchAll();$recent=$pdo->query('SELECT r.registration_code,r.created_at,u.name participant,e.title event_title FROM registrations r JOIN users u ON u.id=r.user_id JOIN events e ON e.id=r.event_id ORDER BY r.created_at DESC LIMIT 6')->fetchAll();require __DIR__.'/../includes/admin-layout.php'; ?><div class="row g-3 mb-4"><?php foreach([['Total events',$stats['events'],'bi-calendar-event'],['Upcoming published',$stats['upcoming'],'bi-calendar2-check'],['Registrations',$stats['registrations'],'bi-ticket-perforated'],['Checked in',$stats['checked'],'bi-qr-code-scan'],['Not checked in',$stats['notchecked'],'bi-hourglass-split'],['Participants',$stats['participants'],'bi-people']] as $st): ?><div class="col-6 col-xl-4"><div class="stat-card h-100"><span class="stat-icon"><i class="bi <?=e($st[2])?>"></i></span><div class="stat-value mt-3"><?=number_format($st[1])?></div><div class="muted"><?=e($st[0])?></div></div></div><?php endforeach; ?></div><div class="row g-4"><div class="col-xl-7"><div class="panel"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 mb-0">Event capacity overview</h2><a href="events.php">Manage events</a></div><div class="table-responsive"><table class="table"><thead><tr><th>Event</th><th>Date</th><th>Registrations</th><th>Fill</th></tr></thead><tbody><?php foreach($events as $ev):$pct=min(100,round($ev['registered']/max(1,$ev['capacity'])*100)); ?><tr><td><strong><?=e($ev['title'])?></strong><div class="small muted"><?=e($ev['status'])?></div></td><td><?=e(date('M j, Y',strtotime($ev['event_date'])))?></td><td><?=number_format($ev['registered'])?> / <?=number_format($ev['capacity'])?></td><td style="min-width:100px"><div class="progress" style="height:7px"><div class="progress-bar" style="width:<?=$pct?>%"></div></div><small class="muted"><?=$pct?>%</small></td></tr><?php endforeach; ?><?php if(!$events): ?><tr><td colspan="4" class="text-center muted">No events yet. Create your first event.</td></tr><?php endif; ?></tbody></table></div><a href="create-event.php" class="btn btn-primary">Create event</a></div></div><div class="col-xl-5"><div class="panel"><h2 class="h5 mb-3">Recent registrations</h2><?php foreach($recent as $r): ?><div class="d-flex gap-3 py-3 border-bottom"><span class="stat-icon"><i class="bi bi-ticket"></i></span><div><strong><?=e($r['participant'])?></strong><div class="muted small"><?=e($r['event_title'])?></div><div class="muted small"><?=e($r['registration_code'])?> · <?=e(date('M j, g:i A',strtotime($r['created_at'])))?></div></div></div><?php endforeach; ?><?php if(!$recent): ?><p class="muted">Registration activity will appear here.</p><?php endif; ?><a href="registrations.php" class="btn btn-outline-primary mt-3">View registrations</a></div></div></div><?php require __DIR__.'/../includes/admin-footer.php'; ?>
